import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Uses the Quickselect algorithm to find the k-th largest element
    in an unsorted list. The expected time complexity is O(n), 
    while the worst-case time complexity is O(n^2).
    """
    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # For k-th largest, > is used instead of <
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        # Move pivot to its final place
        nums[store_index], nums[right] = nums[right], nums[store_index]
        return store_index

    def quickselect(left, right, k_smallest):
        if left == right:
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return quickselect(left, pivot_index - 1, k_smallest)
        else:
            return quickselect(pivot_index + 1, right, k_smallest)

    return quickselect(0, len(nums) - 1, k - 1)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Uses a Max-Heap approach to find the k-th largest element in an unsorted list.
    The time complexity is O(n log k), where n is the number of elements in the list.
    """
    import heapq

    if k <= 0 or k > len(nums):
        raise ValueError("k must be between 1 and the length of nums.")

    # Create a min-heap with the k largest elements
    min_heap = []

    for num in nums:
        if len(min_heap) < k:
            heapq.heappush(min_heap, num)
        else:
            if num > min_heap[0]:
                heapq.heappop(min_heap)
                heapq.heappush(min_heap, num)

    return min_heap[0]
